# Adaptive Pumpenleistung je Richtung, Version 00.02, Stand 08.10.2026 (PyPilot-AI).
# Entwurf: 1-tinypilot/regler/entwurf_pumpenleistung.md; Anlass: 1-tinypilot/docs/tests/2026-10-08_Hafen_Pumpe_Drehzahl_Spannung.md
# Der gekaufte Controller versagt rueckwaerts ab Befehl 0,90 bei Ruhe ~12,6 V; Absenken wirkt sofort im laufenden Lauf.
# Erkennt den Ausfall (Strom klein UND Ruder steht), senkt die Grenze dieser Richtung um 5 % (keine Untergrenze ausser der
# Technik: 5 %, darunter liefe die Pumpe nicht mehr) und gibt sie bei mindestens 1,0 V hoeherer Ruhespannung (60 s) wieder frei.
# Reine Logik ohne pypilot, damit am PC pruefbar (1-tinypilot/regler/leistung_test.py).

VERSION = '00.02'
SCHRITT = 5.0        # % je Absenkung (Betreiber 08.10.2026)
MIN_GRENZE = 5.0     # % technisch: 0 % hiesse Pumpe aus – das entscheidet der Betreiber, nicht das Programm
I_FEHL = 2.0         # A: darunter ist der Lauf verdaechtig (gestoert 1,0-1,3 A, normal ab 2,6 A; Hafen 08.10.)
T_ANLAUF = 0.4       # s nach Laufbeginn bzw. Absenkung, bevor geprueft wird
T_PRUEF = 1.0        # s Pruefdauer (Strom und Ruderweg)
VERZ = 0.5           # s Verzoegerung der Ruderanzeige
WEG_MIN = 0.5        # Grad: kleinste Schwelle "Ruder steht" in T_PRUEF
V100 = 4.5          # Grad/s Ruder rueckwaerts bei 100 % (Hafen 08.10.: 85 % -> 3,8 Grad/s)
K_WEG = 0.35        # Ruder steht = weniger als 35 % der normalen Geschwindigkeit (gestoert kroch es mit 0,3-0,7 Grad/s)
I_RUHE = 0.5         # A: darunter gilt die Pumpe als stehend (Ruhespannung)
T_RUHE = 2.0         # s Mittelung der Ruhespannung
DU_HOCH = 1.0        # V: so viel hoeher muss die Ruhespannung sein (Betreiber 08.10.2026)
T_HOCH = 60.0        # s ununterbrochen, bevor freigegeben wird (Hysterese)
T_SCHNELL = 0.4      # s: nach einem bestaetigten Ausfall im selben Lauf genuegt der Strom (Hafen 08.10.: Absenken wirkt sofort)
G_SCHNELL = 50.0     # %: nur oberhalb; darunter ist der normale Strom klein, dann wieder volle Pruefung mit Ruderweg

class Leistungsgrenze(object):
    """grenze/uref: dict {+1: Wert, -1: Wert} mit .value und .set() (pypilot-Werte); log(text): Meldung."""
    def __init__(self, grenze, uref, log):
        self.grenze, self.uref, self.log = grenze, uref, log
        self.dir = 0               # laufende Richtung
        self.t_bezug = 0.0         # Laufbeginn bzw. letzte Absenkung
        self.hist = []             # (t, Strom, Spannung, Ruder) der letzten Sekunden
        self.u_ruhe = None         # letzte gemittelte Ruhespannung
        self.t_hoch = {1: None, -1: None}
        self.bestaetigt = False    # im laufenden Lauf schon ein Ausfall mit Ruderweg bestaetigt

    def reset(self, grund):
        """Beide Richtungen auf 100 % (Einschalten des Autopiloten; Neustart: Werte sind nicht gespeichert)."""
        for d in (1, -1):
            if self.grenze[d].value < 100.0:
                self.log('Leistung %s %.0f -> 100 %%;%s' % (self._name(d), self.grenze[d].value, grund))
                self.grenze[d].set(100.0)
            self.uref[d].set(0.0)
            self.t_hoch[d] = None
        self.bestaetigt = False

    def faktor(self, richtung):
        """Hoechste erlaubte Geschwindigkeit (0..1) fuer diese Richtung."""
        return self.grenze[richtung].value / 100.0

    def _name(self, d):
        return 'vorwaerts' if d > 0 else 'rueckwaerts'

    def update(self, t, befehl, strom, spannung, ruder):
        d = 1 if befehl > 0 else (-1 if befehl < 0 else 0)
        self.hist.append((t, strom or 0.0, spannung or 0.0, ruder if isinstance(ruder, (int, float)) and not isinstance(ruder, bool) else None))   # pypilot: False = keine Anzeige
        while self.hist and self.hist[0][0] < t - 5.0:
            self.hist.pop(0)
        if d != self.dir:
            self.dir, self.t_bezug, self.bestaetigt = d, t, False
        if d == 0:
            self._ruhe(t)
            return
        self.t_hoch = {1: None, -1: None}     # Freigabe nur bei stehender Pumpe
        if self.bestaetigt and self.grenze[d].value > G_SCHNELL:
            if t - self.t_bezug >= T_ANLAUF + T_SCHNELL:
                kurz = [h[1] for h in self.hist if h[0] >= t - T_SCHNELL]
                if kurz and max(kurz) < I_FEHL:
                    self._senken(t, d, max(kurz))
            return
        if t - self.t_bezug < T_ANLAUF + T_PRUEF + VERZ:
            return
        fenster = [h for h in self.hist if h[0] >= t - T_PRUEF]
        if not fenster or max(h[1] for h in fenster) >= I_FEHL:
            return
        r0 = [h[3] for h in self.hist if t - T_PRUEF - VERZ - 0.2 <= h[0] <= t - T_PRUEF - VERZ and h[3] is not None]
        r1 = [h[3] for h in self.hist if h[0] >= t - 0.2 and h[3] is not None]
        if not r0 or not r1:
            return                              # ohne Ruderanzeige keine Absenkung (Bedingung b fehlt)
        weg = (sum(r1) / len(r1) - sum(r0) / len(r0)) * d
        if weg >= max(WEG_MIN, K_WEG * V100 * self.grenze[d].value / 100.0 * T_PRUEF):
            return
        self.bestaetigt = True
        self._senken(t, d, max(h[1] for h in fenster))

    def _senken(self, t, d, strom):
        alt = self.grenze[d].value
        neu = max(MIN_GRENZE, alt - SCHRITT)
        if neu < alt:
            self.grenze[d].set(neu)
            # Bezug: letzte Ruhespannung; fehlt sie (Lauf gleich nach dem Start), die hoechste Spannung der letzten Sekunden
            ref = self.u_ruhe if self.u_ruhe is not None else max(h[2] for h in self.hist)
            self.uref[d].set(round(ref, 2))
            self.log('Leistung %s %.0f -> %.0f %%;Strom %.1f A;Bezug %.2f V' % (self._name(d), alt, neu, strom, ref))
        self.t_bezug = t                        # naechste Pruefung erst nach erneutem Anlauf

    def _ruhe(self, t):
        werte = [h[2] for h in self.hist if h[0] >= t - T_RUHE and h[1] < I_RUHE and h[2] > 0]
        if len(werte) < 3 or self.hist[0][0] > t - T_RUHE + 0.3:
            return
        self.u_ruhe = sum(werte) / len(werte)
        for d in (1, -1):
            if self.grenze[d].value >= 100.0:
                self.t_hoch[d] = None
                continue
            ref = self.uref[d].value
            if ref and self.u_ruhe >= ref + DU_HOCH:
                if self.t_hoch[d] is None:
                    self.t_hoch[d] = t
                elif t - self.t_hoch[d] >= T_HOCH:
                    alt = self.grenze[d].value
                    self.grenze[d].set(100.0)
                    self.t_hoch[d] = None
                    self.log('Leistung %s %.0f -> 100 %%;Ruhe %.2f V (Bezug %.2f V)' % (self._name(d), alt, self.u_ruhe, ref))
            else:
                self.t_hoch[d] = None
